style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com") {
/* ==== 전체 배경 ==== */
  html, body {
    background: url("https://images5.alphacoders.com/423/thumb-1920-423529.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
  }

  /* ==== 반투명 UI 창 ==== */
  .container, .content, .section, .card, .rbx-card, .modal-content,
  .dropdown-menu, .navbar, .site-header, .footer, .sidebar, .profile-header {
    background: rgba(0, 0, 0, 0.35) !important; /* 투명도 조정 가능 */
    backdrop-filter: blur(10px) !important; /* 블러 효과 */
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.5) !important;
  }

  /* ==== 텍스트 / 아이콘 ==== */
  * {
    color: #ff1a2a !important;
  }
  svg, svg *, i, .icon {
    fill: #ff1a2a !important;
    stroke: #ff1a2a !important;
  }

  /* ==== 버튼 ==== */
  .btn, button, [role="button"], .rbx-btn {
    background: rgba(255, 26, 42, 0.7) !important;
    border: 1px solid rgba(255, 26, 42, 0.8) !important;
    color: #fff !important;
    transition: all 0.2s ease !important;
  }
  .btn:hover, button:hover {
    background: rgba(255, 26, 42, 1) !important;
  }

  /* ==== 입력창 ==== */
  input, textarea, select {
    background: rgba(0, 0, 0, 0.3) !important;
    color: #ff1a2a !important;
    border: 1px solid rgba(255, 26, 42, 0.4) !important;
  }

  /* ==== 스크롤바 ==== */
  ::-webkit-scrollbar-thumb { background: rgba(255,26,42,.6); border-radius: 8px; }
  ::-webkit-scrollbar-track { background: rgba(0,0,0,.4); }

  /* ==== 모달, 팝업 ==== */
  .modal-backdrop { background: rgba(0, 0, 0, 0.6) !important; }
}
